/**
 * Writes `docs/audit/import-report.md`: what the planner did with each old product and what
 * it could not resolve. No database needed.
 *
 *   npm run audit:import
 */
import { writeFileSync } from 'node:fs'

import { planProducts } from './woo-plan'

const plan = planProducts()
const withIssues = plan.filter((p) => p.issues.length)
const count = (test: (p: (typeof plan)[number]) => boolean) => plan.filter(test).length

const lines = [
  '# Import report',
  '',
  'Generated by `npm run audit:import` from `products-raw.json`. Do not edit by hand.',
  '',
  `- ${plan.length} products from ${plan.reduce((n, p) => n + p.legacy.length, 0)} old records.`,
  `- ${count((p) => p.variants.length > 1)} products merged from pack-size families.`,
  `- ${count((p) => p.doses.length > 0)} products with dose rows (${plan.reduce((n, p) => n + p.doses.length, 0)} rows).`,
  `- ${count((p) => p.ingredients.length > 0)} products with active ingredients.`,
  `- ${count((p) => p.status === 'draft')} held back as drafts.`,
  `- ${withIssues.length} products with something to check.`,
  '',
  '## To check',
  '',
  ...withIssues.flatMap((p) => [
    `**${p.name.ro}** (\`${p.slug}\`)`,
    '',
    ...p.issues.map((i) => `- ${i}`),
    '',
  ]),
]
writeFileSync('docs/audit/import-report.md', `${lines.join('\n').trimEnd()}\n`)
console.log(lines.slice(4, 10).join('\n'))
